import type { Point } from './coordinates.js';

/**
 * DataChannel protocol between the client PWA and the host PWA.
 * All messages are JSON, versioned by `proto`.
 */

export const PROTOCOL_VERSION = 1;
export const DATA_CHANNEL_LABEL = 'input';

/** Client -> Host touch/key injection. Coordinates are normalized [0,1]. */
export type ClientMessage =
  | ClientTap
  | ClientSwipe
  | ClientPinch
  | ClientLongPress
  | ClientKey;

/** Host -> Client session info. */
export type HostMessage = HostHello | HostSession;

export interface ClientTap {
  type: 'tap';
  p: Point;
}

export interface ClientSwipe {
  type: 'swipe';
  from: Point;
  to: Point;
  durationMs: number;
}

export interface ClientPinch {
  type: 'pinch';
  c: Point;
  distanceFrom: number;
  distanceTo: number;
  durationMs: number;
}

export interface ClientLongPress {
  type: 'longpress';
  p: Point;
  durationMs: number;
}

export type KeyCode =
  | 'back'
  | 'home'
  | 'recents'
  | 'power'
  | 'volume_up'
  | 'volume_down'
  | 'menu'
  | 'enter';

export interface ClientKey {
  type: 'key';
  key: KeyCode;
}

export interface HostHello {
  type: 'hello';
  proto: number;
  /** Pixel size of the captured video stream. */
  video: { w: number; h: number };
  /** Logical dpi of the device (optional). */
  dpi: number | null;
  /** Whether audio is part of the stream. */
  audio: boolean;
}

export interface HostSession {
  type: 'session';
  state: 'connected' | 'ended' | 'error';
  reason?: string;
}

export function isClientMessage(value: unknown): value is ClientMessage {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as { type?: unknown };
  return (
    v.type === 'tap' ||
    v.type === 'swipe' ||
    v.type === 'pinch' ||
    v.type === 'longpress' ||
    v.type === 'key'
  );
}

export function encodeClientMessage(msg: ClientMessage): string {
  return JSON.stringify(msg);
}

export function decodeClientMessage(data: string): ClientMessage | null {
  try {
    const value: unknown = JSON.parse(data);
    return isClientMessage(value) ? value : null;
  } catch {
    return null;
  }
}

/**
 * Signaling protocol relayed over the LAN WebSocket server.
 * The server is a dumb room relay: every message sent to a room is
 * broadcast to the other peers in the same room.
 */

export type SignalingMessage =
  | { kind: 'join'; role: 'host' | 'client' }
  | { kind: 'peer_joined'; role: 'host' | 'client' }
  | { kind: 'offer'; sdp: string }
  | { kind: 'answer'; sdp: string }
  | { kind: 'ice'; candidate: string; mid: string | null };

export function encodeSignalingMessage(msg: SignalingMessage): string {
  return JSON.stringify(msg);
}

export function decodeSignalingMessage(data: string): SignalingMessage | null {
  try {
    const value = JSON.parse(data);
    if (typeof value !== 'object' || value === null) return null;
    const v = value as { kind?: unknown };
    if (v.kind === 'peer_joined') return value as SignalingMessage;
    if (v.kind === 'ice') {
      if (typeof value.candidate !== 'string') return null;
      return value as SignalingMessage;
    }
    if (v.kind === 'offer' || v.kind === 'answer') {
      if (typeof value.sdp !== 'string') return null;
      return value as SignalingMessage;
    }
    if (v.kind === 'join') {
      if (value.role !== 'host' && value.role !== 'client') return null;
      return value as SignalingMessage;
    }
    return null;
  } catch {
    return null;
  }
}

export * from './coordinates.js';
export * from './protocol.js';
export * from './signaling.js';

import { describe, expect, it } from 'vitest';
import {
  clampPoint,
  denormalize,
  normalize,
  normalizedFromElement,
  remap,
  type Size,
} from '../src/coordinates.js';

const frame: Size = { w: 1920, h: 1080 };

describe('normalize/denormalize', () => {
  it('maps pixels to [0,1] and back', () => {
    const p = { x: 960, y: 540 };
    const n = normalize(p, frame);
    expect(n.x).toBeCloseTo(0.5);
    expect(n.y).toBeCloseTo(0.5);
    const back = denormalize(n, frame);
    expect(back.x).toBe(960);
    expect(back.y).toBe(540);
  });

  it('clamps out-of-range points', () => {
    const n = normalize({ x: -100, y: 2000 }, frame);
    expect(n).toEqual({ x: 0, y: 1 });
    expect(clampPoint({ x: 5000, y: -5 }, frame)).toEqual({ x: 1920, y: 0 });
  });

  it('survives resolution changes via remap', () => {
    const n = normalize({ x: 1920, y: 540 }, frame);
    const smaller: Size = { w: 800, h: 450 };
    const p = remap(n, frame, smaller);
    expect(denormalize(p, smaller)).toEqual({ x: 800, y: 225 });
  });
});

describe('normalizedFromElement (letterbox)', () => {
  function el(overrides: Partial<DOMRect> = {}): DOMRect {
    const base: DOMRect = {
      x: 0,
      y: 0,
      left: 0,
      top: 0,
      right: 400,
      bottom: 300,
      width: 400,
      height: 300,
      toJSON: () => ({}),
    };
    return { ...base, ...overrides };
  }

  it('maps the video area when container has the same aspect ratio', () => {
    const video = { videoWidth: 1600, videoHeight: 900 };
    const bounds = el();
    expect(normalizedFromElement(200, 150, video, bounds)).toEqual({ x: 0.5, y: 0.5 });
  });

  it('handles letterbox on the right (wider container)', () => {
    const video = { videoWidth: 1600, videoHeight: 900 };
    const bounds = el({ left: 10, top: 5, width: 400, height: 300 });
    // scale = min(400/1600, 300/900) = 0.25 -> content 400x225, height fits full.
    const left = 10;
    const top = 5 + (300 - 225) / 2;
    expect(normalizedFromElement(left + 200, top + 112.5, video, bounds)).toEqual({
      x: 0.5,
      y: 0.5,
    });
  });

  it('returns null when video has no dimensions', () => {
    const video = { videoWidth: 0, videoHeight: 0 };
    expect(normalizedFromElement(10, 10, video, el())).toBeNull();
  });

  it('returns null for taps on the black bar', () => {
    const video = { videoWidth: 1600, videoHeight: 900 };
    const bounds = el({ left: 0, top: 0, width: 400, height: 300 });
    // Black bar top area (content starts at y=37.5)
    expect(normalizedFromElement(200, 10, video, bounds)).toBeNull();
  });
});

import { describe, expect, it } from 'vitest';
import {
  decodeClientMessage,
  isClientMessage,
  PROTOCOL_VERSION,
  type ClientMessage,
} from '../src/protocol.js';

describe('client message codec', () => {
  it('round-trips a tap message', () => {
    const raw = JSON.stringify({ type: 'tap', p: { x: 0.5, y: 0.25 } });
    const msg = decodeClientMessage(raw);
    expect(msg).toEqual({ type: 'tap', p: { x: 0.5, y: 0.25 } });
  });

  it('isClientMessage rejects malformed payloads', () => {
    expect(isClientMessage({ type: 'nope' })).toBe(false);
    expect(isClientMessage({ type: 'tap' })).toBe(true);
    expect(isClientMessage('tap')).toBe(false);
    expect(isClientMessage(null)).toBe(false);
  });

  it('rejects invalid JSON', () => {
    expect(decodeClientMessage('{not json')).toBeNull();
  });

  it('exposes a stable protocol version', () => {
    expect(PROTOCOL_VERSION).toBe(1);
  });

  it('accepts all known input kinds', () => {
    const kinds: ClientMessage['type'][] = ['tap', 'swipe', 'pinch', 'longpress', 'key'];
    for (const kind of kinds) {
      expect(isClientMessage({ type: kind, p: { x: 0, y: 0 } })).toBe(true);
    }
  });
});

{
