    this.pc?.close();
    this.ws?.close();
    this.pc = null;
    this.ws = null;
    this.channel = null;
    this.ui.video.srcObject = null;
    this.ui.connect.disabled = false;
    this.ui.disconnect.disabled = true;
    this.enableKeys(false);
    this.status(reason);
  }
}

// keep decodeClientMessage referenced for symmetry when logging locally
export { decodeClientMessage };

