import { ClientSession } from './client.js';
import { TouchToMessage } from './input.js';

function el<T extends HTMLElement>(id: string): T {
  const node = document.getElementById(id);
  if (!node) throw new Error(`#${id} not found`);
  return node as T;
}

const video = el<HTMLVideoElement>('screen');
const session = new ClientSession({
  signalUrl: el('signal-url'),
  room: el('room'),
  connect: el('connect'),
  disconnect: el('disconnect'),
  home: el('home'),
  back: el('back'),
  video,
  status: el('status'),
  touchHint: el('touch'),
});

const touch = new TouchToMessage({ video }, { sendInput: (m) => session.sendInput(m) });

const stage = document.querySelector('.stage') as HTMLElement | null;
if (stage) {
  stage.addEventListener('pointerdown', (e) => touch.pointerDown(e as PointerEvent));
  stage.addEventListener('pointermove', (e) => touch.pointerMove(e as PointerEvent));
  stage.addEventListener('pointerup', (e) => touch.pointerUp(e as PointerEvent));
  stage.addEventListener('pointercancel', (e) => touch.pointerCancel(e as PointerEvent));
}

el('connect').addEventListener('click', () => session.connect());
el('disconnect').addEventListener('click', () => session.disconnect());
el('home').addEventListener('click', () => session.sendKey('home'));
el('back').addEventListener('click', () => session.sendKey('back'));

if ('serviceWorker' in navigator) {
  void navigator.serviceWorker.register('./sw.js').catch(() => undefined);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  overscroll-behavior: none;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background: #0f1117;
  color: #e6e8ef;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  height: 100vh;
}

header h1 {
  margin: 0;
  font-size: 20px;
}

.sub {
  margin: 4px 0 0;
  color: #8b94a7;
  font-size: 13px;
}

.controls {
  display: grid;
  grid-template-columns: 1fr 1fr auto auto;
  gap: 8px;
  align-items: end;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: #8b94a7;
}

.field input {
  padding: 8px;
  border-radius: 8px;
  border: 1px solid #2a3040;
  background: #171b24;
  color: #e6e8ef;
}

button {
  padding: 10px 12px;
  border: 0;
  border-radius: 10px;
  font-size: 14px;
  cursor: pointer;
  background: #2a3040;
  color: #e6e8ef;
}

button.primary {
  background: #3d7eff;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.stage {
  position: relative;
  flex: 1;
  border-radius: 12px;
  overflow: hidden;
  background: #000;
  min-height: 240px;
}

video {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
  border-radius: 12px;
}

.status {
  position: absolute;
  left: 8px;
  top: 8px;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.65);
  font-size: 12px;
}

.touch-hint {
  position: absolute;
  right: 8px;
  bottom: 8px;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.65);
  font-size: 11px;
  color: #9aa3b8;
}

{
  "name": "ACLG Client",
  "short_name": "ACLG",
  "start_url": ".",
  "display": "standalone",
  "orientation": "landscape",
  "background_color": "#0f1117",
  "theme_color": "#0f1117",
  "icons": [
    {
      "src": "icon.svg",
      "sizes": "any",
      "type": "image/svg+xml"
    }
  ]
}

const CACHE = 'aclg-client-v1';
const ASSETS = ['./', './index.html', './manifest.webmanifest', './icon.svg'];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)));
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))),
    ),
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  event.respondWith(
    fetch(request)
      .then((response) => {
        const clone = response.clone();
        caches.open(CACHE).then((c) => c.put(request, clone)).catch(() => undefined);
        return response;
      })
      .catch(() => caches.match(request).then((hit) => hit ?? caches.match('./index.html'))),
  );
});

