/**
 * Remap an ABSOLUTE pixel point from one frame size to another
 * (e.g. after the host's encoder changed resolution). Input and output
 * are pixel coordinates within their respective frames.
 */
export function remap(p: Point, from: Size, to: Size): Point {
  return {
    x: from.w === 0 ? p.x : (p.x * to.w) / from.w,
    y: from.h === 0 ? p.y : (p.y * to.h) / from.h,
  };
}

