export function normalizedFromElement(
  clientX: number,
  clientY: number,
  video: Pick<HTMLVideoElement, 'videoWidth' | 'videoHeight'> | { videoWidth: number; videoHeight: number },
  bounds: DOMRect,
): Point | null {
  const vw = video.videoWidth;
  const vh = video.videoHeight;
  if (!vw || !vh) return null;

  const scale = Math.min(bounds.width / vw, bounds.height / vh);
  const boxWidth = vw * scale;
  const boxHeight = vh * scale;
  const offsetX = (bounds.width - boxWidth) / 2;
  const offsetY = (bounds.height - boxHeight) / 2;

  const relX = clientX - bounds.left;
  const relY = clientY - bounds.top;
  if (relX < offsetX || relX > offsetX + boxWidth || relY < offsetY || relY > offsetY + boxHeight) {
    return null;
  }
  return { x: (relX - offsetX) / boxWidth, y: (relY - offsetY) / boxHeight };
}

