class MainActivity : AppCompatActivity() {

    private val status: TextView get() = findViewById(R.id.status)

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)
        findViewById<Button>(R.id.start).setOnClickListener { startHelper() }
        findViewById<Button>(R.id.stop).setOnClickListener { stopHelper() }
        findViewById<Button>(R.id.accessibility).setOnClickListener {
            startActivity(Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))
        }
        refresh()
    }

    override fun onResume() {
        super.onResume()
        refresh()
    }

    private fun startHelper() {
        startForegroundService(Intent(this, HelperService::class.java))
    }

    private fun stopHelper() {
        stopService(Intent(this, HelperService::class.java))
    }

    private fun refresh() {
        val isRunning = isServiceRunning(HelperService::class.java)
        val accEnabled = isAccessibilityEnabled()
        status.text = buildString {
            append("Сервис: ").append(if (isRunning) "вкл" else "выкл").append('\n')
            append("Спец. возможности (инпут): ").append(if (accEnabled) "вкл" else "ВЫКЛ — без инпута\n").append('\n')
            append("WS-порт: 9100 (хосту указать ws://127.0.0.1:9100)")
        }
    }

    private fun isServiceRunning(cls: Class<*>): Boolean {
        val am = getSystemService(Context.ACTIVITY_SERVICE) as android.app.ActivityManager
        return am.getRunningServices(100).any { it.service.className == cls.name }
    }

    private fun isAccessibilityEnabled(): Boolean {
        val expected = ComponentName(this, InputAccessibilityService::class.java).flattenToString()
        val enabled = Settings.Secure.getString(
            contentResolver,
            Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES,
        ) ?: return false
        return enabled.split(':').any { ComponentName.unflattenFromString(it)?.flattenToString() == expected }
    }
}

package com.aclg.helper

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.GestureDescription
import android.graphics.Path
import android.graphics.Point
import android.graphics.Rect
import android.os.Handler
import android.os.Looper
import android.util.DisplayMetrics
import android.view.WindowManager

/**
 * Наивный маршрут «протокол -> жесты». Координаты в сообщениях нормализованы
 * [0,1] относительно видео (те же оси, что у экрана устройства).
 */
object InputBridge {

    private const val TAP_STROke_MS = 80L

    @Volatile
    var service: InputAccessibilityService? = null

    /** Dispatch a protocol message. Returns false if nothing could be injected. */
    fun inject(type: String, args: Map<String, Any>): Boolean {
        val svc = service ?: return false
        if (!svc.rootInActiveWindowCompat && svc.isBoot) {
            // best-effort: если активное окно недоступно — всё равно пробуем жест
        }
        val size = displaySize(svc)
        if (size.isEmpty) return false

        fun p(x: Any?, y: Any?): Point = Point((x as Double * size.w).toInt(), (y as Double * size.h).toInt())

        return when (type) {
            "tap" -> {
                val pt = p(args["p"]?.jsField("x"), args["p"]?.jsField("y"))
                svc.tap(pt)
            }
            "longpress" -> {
                val pt = p(args["p"]?.jsField("x"), args["p"]?.jsField("y"))
                val dur = ((args["durationMs"] as? Number)?.toLong() ?: 600L)
                svc.longPress(pt, dur)
            }
            "swipe" -> {
                val from = p(args["from"]?.jsField("x"), args["from"]?.jsField("y"))
                val to = p(args["to"]?.jsField("x"), args["to"]?.jsField("y"))
                val dur = ((args["durationMs"] as? Number)?.toLong() ?: 180L)
                svc.swipe(from, to, dur)
            }
            "pinch" -> {
                val c = p(args["c"]?.jsField("x"), args["c"]?.jsField("y"))
                val d0 = (args["distanceFrom"] as? Number)?.toFloat() ?: 40f
                val d1 = (args["distanceTo"] as? Number)?.toFloat() ?: 80f
                val dur = ((args["durationMs"] as? Number)?.toLong() ?: 80L)
                svc.pinch(c, d0, d1, dur)
            }
            "key" -> {
                val key = args["key"] as? String ?: return false
                svc.performGlobalActionCompat(key)
            }
            else -> false
        }
    }

    private fun Any?.jsField(name: String): Any? =
        (this as? Map<*, *>)?.get(name)

    private fun displaySize(svc: InputAccessibilityService): Rect {
        val metrics = DisplayMetrics()
        svc.applicationContext.getSystemService(WindowManager::class.java).defaultDisplay
            .getRealMetrics(metrics)
        return Rect(0, 0, metrics.widthPixels, metrics.heightPixels)
    }
}

class InputAccessibilityService : AccessibilityService() {

    private val handler = Handler(Looper.getMainLooper())
    val isBoot: Boolean get() = true
    val rootInActiveWindowCompat: Boolean get() = rootInActiveWindow != null

    override fun onServiceConnected() {
        super.onServiceConnected()
        InputBridge.service = this
    }

    override fun onDestroy() {
        InputBridge.service = null
        super.onDestroy()
    }

    override fun onAccessibilityEvent(event: android.view.accessibility.AccessibilityEvent?) = Unit

    override fun onInterrupt() = Unit

    fun tap(pt: Point) = gesture(listOf(Stroke(pt, pt, null, TAP_STROke_MS)))

    fun longPress(pt: Point, durationMs: Long) =
        gesture(listOf(Stroke(pt, pt, null, durationMs)))

    fun swipe(from: Point, to: Point, durationMs: Long) =
        gesture(listOf(Stroke(from, to, null, durationMs)))

    fun pinch(center: Point, d0: Float, d1: Float, durationMs: Long) {
        val pathA = Path().apply { moveTo(center.x - d0 / 2, center.y); lineTo(center.x - d1 / 2, center.y) }
        val pathB = Path().apply { moveTo(center.x + d0 / 2, center.y); lineTo(center.x + d1 / 2, center.y) }
        val desc = GestureDescription.Builder()
            .addStroke(GestureDescription.StrokeDescription(pathA, 0, durationMs))
            .addStroke(GestureDescription.StrokeDescription(pathB, 0, durationMs))
            .build()
        dispatchGesture(desc, null, handler)
    }

    fun performGlobalActionCompat(key: String): Boolean = when (key) {
        "back" -> performGlobalAction(GLOBAL_ACTION_BACK)
        "home" -> performGlobalAction(GLOBAL_ACTION_HOME)
        "recents" -> performGlobalAction(GLOBAL_ACTION_RECENTS)
        "power" -> performGlobalAction(GLOBAL_ACTION_POWER_DIALOG)
        "menu" -> performGlobalAction(GLOBAL_ACTION_NOTIFICATIONS)
        else -> false
    }

    private data class Stroke(
        val from: Point,
        val to: Point,
        val mid: Point?,
        val durationMs: Long,
    )

    private fun gesture(strokes: List<Stroke>): Boolean {
        if (strokes.isEmpty()) return false
        val builder = GestureDescription.Builder()
        for (s in strokes) {
            val path = Path().apply { moveTo(s.from.x.toFloat(), s.from.y.toFloat()) }
            if (s.mid != null) path.lineTo(s.mid.x.toFloat(), s.mid.y.toFloat())
            if (s.from == s.to) {
                // одиночное касание: линия в соседний пиксель с последующим отпусканием
                path.lineTo(s.from.x.toFloat() + 1f, s.from.y.toFloat() + 1f)
            } else {
                path.lineTo(s.to.x.toFloat(), s.to.y.toFloat())
            }
            builder.addStroke(GestureDescription.StrokeDescription(path, 0, s.durationMs))
        }
        return dispatchGesture(builder.build(), null, handler)
    }
}

