class InputAccessibilityService : AccessibilityService() {

    private val handler = Handler(Looper.getMainLooper())

    override fun onServiceConnected() {
        super.onServiceConnected()
        InputBridge.service = this
    }

    override fun onDestroy() {
        InputBridge.service = null
        super.onDestroy()
    }

    override fun onAccessibilityEvent(event: android.view.accessibility.AccessibilityEvent?) = Unit

    override fun onInterrupt() = Unit

    fun tap(pt: Point): Boolean = gesture(listOf(TapStroke(pt)))

    fun longPress(pt: Point, durationMs: Long): Boolean =
        gesture(listOf(MoveStroke(pt, pt, durationMs)))

    fun swipe(from: Point, to: Point, durationMs: Long): Boolean =
        gesture(listOf(MoveStroke(from, to, durationMs)))

    fun pinch(center: Point, d0: Float, d1: Float, durationMs: Long): Boolean {
        val left = Point((center.x - d0 / 2).toInt(), center.y)
        val leftEnd = Point((center.x - d1 / 2).toInt(), center.y)
        val right = Point((center.x + d0 / 2).toInt(), center.y)
        val rightEnd = Point((center.x + d1 / 2).toInt(), center.y)
        val pathA = Path().apply { moveTo(left.x.toFloat(), left.y.toFloat()); lineTo(leftEnd.x.toFloat(), leftEnd.y.toFloat()) }
        val pathB = Path().apply { moveTo(right.x.toFloat(), right.y.toFloat()); lineTo(rightEnd.x.toFloat(), rightEnd.y.toFloat()) }
        val desc = GestureDescription.Builder()
            .addStroke(GestureDescription.StrokeDescription(pathA, 0, durationMs))
            .addStroke(GestureDescription.StrokeDescription(pathB, 0, durationMs))
            .build()
        return dispatchGesture(desc, null, handler)
    }

    fun performGlobalActionCompat(key: String): Boolean = when (key) {
        "back" -> performGlobalAction(GLOBAL_ACTION_BACK)
        "home" -> performGlobalAction(GLOBAL_ACTION_HOME)
        "recents" -> performGlobalAction(GLOBAL_ACTION_RECENTS)
        "power" -> performGlobalAction(GLOBAL_ACTION_POWER_DIALOG)
        "menu" -> performGlobalAction(GLOBAL_ACTION_NOTIFICATIONS)
        else -> false
    }

    private sealed class GestureStroke {
        abstract fun path(): Path
        abstract val durationMs: Long
    }

    private class TapStroke(val pt: Point) : GestureStroke() {
        override val durationMs = 80L
        override fun path(): Path = Path().apply {
            moveTo(pt.x.toFloat(), pt.y.toFloat())
            lineTo(pt.x.toFloat() + 1f, pt.y.toFloat() + 1f)
        }
    }

    private class MoveStroke(
        val from: Point,
        val to: Point,
        override val durationMs: Long,
    ) : GestureStroke() {
        override fun path(): Path = Path().apply {
            moveTo(from.x.toFloat(), from.y.toFloat())
            lineTo(to.x.toFloat(), to.y.toFloat())
        }
    }

    private fun gesture(strokes: List<GestureStroke>): Boolean {
        if (strokes.isEmpty()) return false
        val builder = GestureDescription.Builder()
        for (s in strokes) {
            builder.addStroke(GestureDescription.StrokeDescription(s.path(), 0, s.durationMs))
        }
        return dispatchGesture(builder.build(), null, handler)
    }
}

package com.aclg.helper

import java.io.BufferedInputStream
import java.io.ByteArrayOutputStream
import java.io.DataInputStream
import java.io.OutputStream
import java.net.ServerSocket
import java.net.Socket
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import java.util.Base64

/**
 * Минимальный WebSocket-сервер (текстовые кадры) на чистой Java-стандартной
 * библиотеке — без внешних зависимостей. Достаточен, чтобы хост-PWA слал
 * сообщения инпута на ws://127.0.0.1:9100.
 */
class WsServer(
    private val port: Int,
    private val onMessage: (String) -> Unit,
    private val onClientChange: (Int) -> Unit,
) : AutoCloseable {

    private val server = ServerSocket(port)
    @Volatile private var running = true
    private val clients = java.util.concurrent.CopyOnWriteArraySet<Socket>()
    private val threads = mutableListOf<Thread>()

    fun start() {
        val t = Thread({ loop() }, "aclg-ws")
        t.isDaemon = true
        t.start()
        threads += t
    }

    private fun loop() {
        while (running) {
            try {
                val sock = server.accept()
                clients += sock
                onClientChange(clients.size)
                val h = Thread({ handle(sock) }, "aclg-ws-client")
                h.isDaemon = true
                h.start()
                threads += h
            } catch (_: Exception) {
                if (running) Thread.sleep(50)
            }
        }
    }

    val connectionCount: Int get() = clients.size

    private enum class Op(op: Int) {
        CONTINUATION(0x0), TEXT(0x1), BINARY(0x2), CLOSE(0x8), PING(0x9), PONG(0xA);

        companion object {
            fun from(v: Int): Op? = entries.firstOrNull { it.op == v }
        }
    }

    private fun handle(sock: Socket) {
        try {
            val input = DataInputStream(BufferedInputStream(sock.getInputStream()))
            val output = sock.getOutputStream()

            // --- handshake ---
            val headers = LinkedHashMap<String, String>()
            val requestLine = input.readLineSafe() ?: return
            if (!requestLine.startsWith("GET")) return
            while (true) {
                val line = input.readLineSafe() ?: return
                if (line.isEmpty()) break
                val idx = line.indexOf(':')
                if (idx > 0) headers[line.substring(0, idx).trim().lowercase()] = line.substring(idx + 1).trim()
            }
            val key = headers["sec-websocket-key"] ?: return
            val accept = handshakeAccept(key)
            output.write(
                "HTTP/1.1 101 Switching Protocols\r\n" +
                    "Upgrade: websocket\r\n" +
                    "Connection: Upgrade\r\n" +
                    "Sec-WebSocket-Accept: $accept\r\n\r\n".toByteArray(),
            )
            output.flush()

            // --- frames ---
            var pendingOpcode: Op? = null
            val pending = ByteArrayOutputStream()
            while (running) {
                val b0 = input.read()
                if (b0 < 0) break
                val b1 = input.read()
                if (b1 < 0) break
                val fin = b0 and 0x80 != 0
                val rawOp = b0 and 0x0F
                val masked = b1 and 0x80 != 0
                var len = b1 and 0x7F

                if (len == 126) len = input.readUnsignedShort()
                else if (len == 127) {
                    val hi = input.readLong()
                    len = (hi and 0x7FFF_FFFF_FFFF_FFFFL).toInt()
                }
                val maskKey = if (masked) {
                    ByteArray(4).also { input.readFully(it) }
                } else null
                val payload = ByteArray(len).also { input.readFully(it) }
                if (maskKey != null) {
                    for (i in payload.indices) payload[i] = (payload[i].toInt() xor maskKey[i and 3].toInt()).toByte()
                }

                val op = Op.from(rawOp) ?: continue
                when (op) {
                    Op.TEXT, Op.BINARY, Op.CONTINUATION -> {
                        pendingOpcode = if (op == Op.CONTINUATION) pendingOpcode ?: Op.BINARY else op
                        pending.write(payload)
                        if (fin) {
                            val complete = pending.toByteArray()
                            if (pendingOpcode == Op.TEXT) {
                                onMessage(String(complete, StandardCharsets.UTF_8))
                            }
                            pending.reset()
                            pendingOpcode = null
                        }
                    }
                    Op.CLOSE -> {
                        output.write(frame(Op.CLOSE, byteArrayOf(3, 232)))
                        output.flush()
                        return
                    }
                    Op.PING -> {
                        pong(output, payload)
                    }
                    Op.PONG -> Unit
                }
            }
        } catch (_: Exception) {
            // drop connection
        } finally {
            try {
                sock.close()
            } catch (_: Exception) {
            }
            clients -= sock
            onClientChange(clients.size)
        }
    }

    private fun send(sock: Socket, text: String) {
        try {
            sock.getOutputStream().write(frame(Op.TEXT, text.toByteArray(StandardCharsets.UTF_8)))
            sock.getOutputStream().flush()
        } catch (_: Exception) {
        }
    }

    fun broadcast(text: String) {
        for (s in clients) send(s, text)
    }

    private fun pong(output: OutputStream, payload: ByteArray) {
        output.write(frame(Op.PONG, payload))
        output.flush()
    }

    private fun frame(op: Op, payload: ByteArray): ByteArray {
        val out = java.io.ByteArrayOutputStream()
        out.write(0x80 or op.op)
        val n = payload.size
        when {
            n < 126 -> out.write(n)
            n < 0x10000 -> {
                out.write(126)
                out.write(n shr 8 and 0xFF)
                out.write(n and 0xFF)
            }
            else -> {
                out.write(127)
                for (i in 7 downTo 0) out.write((n.toLong() shr (i * 8)).toInt() and 0xFF)
            }
        }
        out.write(payload)
        return out.toByteArray()
    }

    private fun handshakeAccept(key: String): String {
        val digest = MessageDigest.getInstance("SHA-1")
            .digest((key + WS_GUID).toByteArray(StandardCharsets.UTF_8))
        return Base64.getEncoder().encodeToString(digest)
    }

    override fun close() {
        running = false
        try {
            server.close()
        } catch (_: Exception) {
        }
        for (s in clients) {
            try {
                s.close()
            } catch (_: Exception) {
            }
        }
    }

    companion object {
        private const val WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    }
}

private fun DataInputStream.readLineSafe(): String? {
    val sb = StringBuilder()
    while (true) {
        val b = read()
        if (b < 0) return if (sb.isEmpty()) null else sb.toString()
        if (b == '\n'.code) {
            val s = sb.toString()
            if (s.endsWith("\r")) sb.setLength(sb.length - 1)
            return s
        }
        sb.append(b.toChar())
        if (sb.length > 16_384) return sb.toString()
    }
}

package com.aclg.helper

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Context
import android.content.Intent
import android.os.Build
import android.os.IBinder
import android.os.PowerManager
import android.util.Log
import org.json.JSONObject

/**
 * Фоновый сервис-мост: держит маленький WebSocket-сервер на 9100 и переводит
 * сообщения инпута (JSON) в жесты через InputBridge/AccessibilityService.
 */
class HelperService : Service() {

    private var ws: WsServer? = null
    private var wakeLock: PowerManager.WakeLock? = null
    private var lastError: String? = null

    override fun onCreate() {
        super.onCreate()
        startForegroundCompat()
        val pm = getSystemService(Context.POWER_SERVICE) as PowerManager
        wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "aclg:helper").apply { acquire() }
        startWs()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int = START_STICKY

    override fun onDestroy() {
        ws?.close()
        ws = null
        wakeLock?.let { if (it.isHeld) it.release() }
        super.onDestroy()
    }

    override fun onBind(intent: Intent?): IBinder? = null

    private fun startWs() {
        try {
            val server = WsServer(9100, this::onWsMessage) { count ->
                Log.i(TAG, "ws clients: $count")
            }
            server.start()
            ws = server
            Log.i(TAG, "WS listening on 9100")
        } catch (e: Exception) {
            lastError = e.message
            Log.e(TAG, "WS start failed", e)
        }
    }

    private fun onWsMessage(raw: String) {
        try {
            val obj = JSONObject(raw)
            val type = obj.getString("type")
            val args = obj.toSerializableArgs()
            val ok = InputBridge.inject(type, args)
            if (!ok) Log.w(TAG, "inject failed for $type (service bound? ${InputBridge.service != null})")
        } catch (e: Exception) {
            Log.w(TAG, "bad ws message: $raw", e)
        }
    }

    private fun startForegroundCompat() {
        val channelId = "aclg_bridge"
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val ch = NotificationChannel(
                channelId,
                "ACLG Bridge",
                NotificationManager.IMPORTANCE_LOW,
            )
            getSystemService(NotificationManager::class.java).createNotificationChannel(ch)
        }
        val openIntent =
            PendingIntent.getActivity(this, 0, Intent(this, MainActivity::class.java), pendingFlags())
        val notif: Notification = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            Notification.Builder(this, channelId)
        } else {
            @Suppress("DEPRECATION") Notification.Builder(this)
        }
            .setSmallIcon(android.R.drawable.ic_menu_manage)
            .setContentTitle(getString(R.string.service_name))
            .setContentText("WS-порт 9100 · включи спец. возможности для инпута")
            .setContentIntent(openIntent)
            .setOngoing(true)
            .build()
        startForeground(1, notif)
    }

    private fun pendingFlags(): Int =
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) PendingIntent.FLAG_IMMUTABLE else 0

    companion object {
        private const val TAG = "ACLGHelper"
    }
}

