import {
  DATA_CHANNEL_LABEL,
  decodeClientMessage,
  encodeSignalingMessage,
  PROTOCOL_VERSION,
  type HostMessage,
  type SignalingMessage,
} from '@aclg/shared';

export interface HostUi {
  capture: HTMLButtonElement;
  stop: HTMLButtonElement;
  signalUrl: HTMLInputElement;
  room: HTMLInputElement;
  helperUrl: HTMLInputElement;
  preview: HTMLVideoElement;
  status: HTMLElement;
  logEl: HTMLElement;
