pc.onconnectionstatechange = () => {
      this.status(`WebRTC: ${pc.connectionState}`);
      if (pc.connectionState === 'connected') {
        this.startStats();
      } else if (pc.connectionState === 'failed' || pc.connectionState === 'closed') {
        this.stopStats();
        this.sendHost({ type: 'session', state: 'ended', reason: pc.connectionState });
      }
    };
    return pc;
  }

  /** Cap the video encoder bitrate on the send side. LAN-friendly, live-updatable. */
  private async applyBitrate(bps: number): Promise<void> {
    if (!this.pc) return;
    const sender = this.pc.getSenders().find((s) => s.track?.kind === 'video');
    if (!sender) return;
    try {
      const params = sender.getParameters();
      if (!params.encodings?.length) return;
      const enc = params.encodings[0];
      const clamped = Math.max(BITRATE_MIN_BPS, Math.min(bps, this.maxUserBitrateBps));
      if (enc.maxBitrate !== clamped) {
        enc.maxBitrate = clamped;
        params.degradationPreference = 'maintain-framerate';
        await sender.setParameters(params);
        this.currentBitrateBps = clamped;
      }
    } catch {
      // браузер может не дать менять параметры в горячем виде — не критично
    }
  }

  private async startStats(): Promise<void> {
    this.stopStats();
    this.lastBytes = 0;
    this.lastTs = performance.now();
    this.statsTimer = window.setInterval(() => void this.statsLoop(), 2000);
  }

  private stopStats(): void {
    if (this.statsTimer !== null) {
      window.clearInterval(this.statsTimer);
      this.statsTimer = null;
    }
  }

  private async statsLoop(): Promise<void> {
    if (!this.pc) return;

    let txBps = 0;
    let fps = 0;
    let lossRatio = 0;
    let rtt = 0;

    try {
      const report = await this.pc.getStats();
      const now = performance.now();
      for (const stat of report.values()) {
        const s = stat as RTCStats;
        if (s.type === 'outbound-rtp' && (s as RTCOutboundRtpStreamStats).kind === 'video') {
          const o = s as RTCOutboundRtpStreamStats;
          if (this.lastBytes > 0) {
            txBps = Math.round(((o.bytesSent - this.lastBytes) * 8 * 1000) / (now - this.lastTs));
          }
          this.lastBytes = o.bytesSent;
          this.lastTs = now;
          fps = o.framesPerSecond ?? 0;
        } else if (s.type === 'remote-inbound-rtp') {
          const r = s as RTCStats & { packetsLost?: number; packetsReceived?: number; roundTripTime?: number };
          const lost = r.packetsLost ?? 0;
          const recv = r.packetsReceived ?? 0;
          if (lost + recv > 0) lossRatio = lost / (lost + recv);
          rtt = (r.roundTripTime ?? 0) * 1000;
        }
      }
    } catch {
      return;
    }

    const prev = this.currentBitrateBps;
    if (this.ui.auto.checked) {
      let next = prev;
      if (lossRatio >= 0.08) next = prev * 0.7;
      else if (lossRatio >= 0.02) next = prev * 0.9;
      else if (lossRatio < 0.005 && rtt < 120) next = Math.min(this.maxUserBitrateBps, prev * 1.05);
      if (next !== prev) await this.applyBitrate(next);
    } else if (prev !== this.maxUserBitrateBps) {
      await this.applyBitrate(this.maxUserBitrateBps);
    }

    this.ui.stats.textContent =
      `↑ ${(txBps / 1_000_000).toFixed(1)} Мбит/с · ${fps} fps · потеря ${(lossRatio * 100).toFixed(1)}%` +
      ` · rtt ${rtt.toFixed(0)} мс · лимит ${(this.currentBitrateBps / 1_000_000).toFixed(1)} Мбит/с`;
  }

